    "purpose": "Öğrencilerin, tarım ürünleri piyasalarında fiyat oluşumu, pazarlama karması unsurları ve tarım ürünleri pazarlarını yönlendiren kuruluşlar hakkında bilgi sahibi olmalarını sağlamak.",
    "content": "Tarım ürünlerinde arz, talep kavramları ve çeşitli piyasalarda fiyat oluşumu ile pazarlama karması ve tarımsal ürün pazarlarını yönlendirici kuruluşlar.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi, uygulama verilerinin değerlendirilmesi ve akademik tartışma.",
    "resources": "Kaynaklar: Gürler, A.Zafer; Analitik Tarım Ekonomisi; Ders Notları: İnan, İ.Hakkı; Tarım Ekonomisi ve İşletmeciliği",
