    "instructor": "Dr. Öğr. Üyesi Neslihan Kılıç",
    "purpose": "Organik tarımın önemi, Dünya’da ve ülkemizde organik tarımın gelişimi, organik tarımın temel amacının kavranması, organik tarımda temel ilkelerin öğretilmesi, organik bitkisel üretim esasları öğretilmesi",
    "content": "Organik tarımın tanımı ve tarihçesi, Türkiye’de ve Dünya’da organik tarımın önemi, Organik Tarım ve çevre ilişkileri Organik tarımda yetiştiricilik esasları,Kontrol ve Sertifikasyon konularında bilgi vermektedir",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi, uygulama verilerinin değerlendirilmesi ve akademik tartışma.",
    "resources": "Kaynaklar: organik Tarımdaki gelişmeler(Prof. Dr. Celal Er-Doç. Dr. Dilek Başalma); Ders Notları: Değişik kaynaklardan yararlanılarak hazırlanmış ders notu ve fotoğraflarla zenginleştirilmiş elektronik ortama aktarılmış sunuorganik Tarımdaki gelişmeler(Prof. Dr. Celal Er-Doç. Dr. Dilek Başalma)",
