      "Yumurtacı ve Etçi Kanatlılar İçin Rasyon Tasarımı-1",
      "Spesifik Üretim Hedeflerine Yönelik Kanatlı Rasyonları-2",
      "NRC ve Modern Rasyon Programlama Yazılımları ile Senaryo Analizleri",
      "Rasyon Hazırlamada Karşılaşılan Teknik Problemler, Antinütrisyonel Faktörler ve Çözüm Yolları",
      "Rasyonun Maliyet-Verimlilik Analizi ve İşletme Ekonomisine Etkisi",
      "Farklı Çevresel Şartlar ve Verim Hedefleri İçin Global Rasyon Stratejileri",
      "Rasyon hazırlama: kapsam ve temel kavramlar"
