    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Dr. Öğr. Üyesi Benian Pinar Aktepe benianaktepe@osmaniye.edu.tr",
    "purpose": "Bu dersin amacı, bitki hastalık etmenlerinin doğru ve güvenilir şekilde tanılanmasına yönelik klasik ve modern teknikleri öğretmek, öğrencilerin laboratuvar temelli teşhis süreçlerini uygulayabilmesini sağlamaktır.",
    "content": "Hastalık etmenlerinin tanılanmasının önemi, bakteriyel patojenlerin izolasyonu ve tanısı, besiyeri hazırlama, Koch postulatları, hastalık belirtileri, patojenite testleri, LOPAT testleri ve önemli bakteriyel bitki patojenlerinin tanılanması.",
    "methods": "Yüz yüze1.hafta – Anlatım + soru-cevap2.hafta – Anlatım + laboratuvar uygulaması3.hafta – Anlatım + uygulama4.hafta – Anlatım + vaka analizi5.hafta – Anlatım + uygulama6.hafta – Anlatım + uygulama7.hafta – Anlatım + tartışma8.hafta – Anlatım + süreç analizi9.hafta – Anlatım + uygulama10.hafta – Anlatım + uygulama11.hafta – Anlatım + vaka analizi12.hafta – Anlatım + vaka analizi13.hafta – Anlatım + örnek inceleme14.hafta – Anlatım + soru-cevap",
    "resources": "Kaynaklar: Agrios, G. N. (2021). Plant pathology (6th ed.). Academic Press. https://www.sciencedirect.com/book/edited-volume/9780128224298/agrios-plant-pathology; Ders Notları: Agrios, G. N. (2021). Plant pathology (6th ed.). Academic Press. https://www.sciencedirect.com/book/edited-volume/9780128224298/agrios-plant-pathologySchaad, N. W., Jones, J. B., & Chun, W. (2001). Laboratory guide for identification of plant pathogenic bacteria. APS Press.Rani Lakshmi Bai Central Agricultural University. (2020). Agricultural microbiology. https://rlbcau.ac.in/wp-content/uploads/2024/09/Agricultural-Microbiology.pdfStella International Publication. (2025). Introduction to plant pathology. https://www.researchgate.net/publication/388270323; Dökümanlar: https://www.sciencedirect.com/book/edited-volume/9780128224298/agrios-plant-pathology",
