    "purpose": "tohum üretimin ilkeleri, teknolojisi, kontrol ve sertifikasyonu ile ilgili bilgi ve becerilerin kazandırılması",
    "content": "Bu derste, tarla bitkileri bölümü lisans öğrencilerine, tohum oluşumu, yapısı, kimyası, fizyolojisi ve tohum işleme teknolojisi hakkında bilgi verilecektir",
    "methods": "Anlatım, gösterip yaptırma, soru-cevap, gözlem, teknik gezi",
    "resources": "Kaynaklar: Dadlani, M., Devendra K. YadavaSeed Science and Technology, 2023; Ders Notları: Dadlani, M., Devendra K. YadavaSeed Science and Technology, 2023; Dökümanlar: https://acikerisim.aku.edu.tr/items/dc6f2b88-ab73-4354-b0b7-4b0bfd7b4953 https://www.researchgate.net/publication/384455446_SEBZECILIKTE_TOHUMUN_ONEMI_VE_TOHUM_URETIMINI_ETKILEYEN_UNSURLAR?utm_source=chatgpt.com",
    "sdgs": [
      "2",
      "9",
      "12"
    ],
    "outcomes": [
      "Tohum teknolojisi kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "İleri organik tarım işletmeciliği alanındaki uygulamaları karşılaştırır.",
      "Tohum teknolojisi için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Tohum teknolojisi faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Tohum teknolojisi bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Tohumun önemi ve temel kavramlar",
      "Dünya ve Türkiyede tohumluk ticareti",
      "Tohumculuk kanunu ve organik tarım yönetmeliği",
      "Bitkilerde üreme ve tohum oluşumu",
      "Tohum morfolojisi ve fizyolojisi (dormansi)",
      "Tohumluk üretiminde ekolojik esaslar",
      "Organik tohumluk üretiminde ön uygulamalar (Priming)",
      "Organik tohumluk üretiminde agronomik esaslar",
      "Tohumluk Tarla kontrolleri ve sınıfları",
      "Tohum numunesi alma yöntemleri ve kalite analizleri",
      "Tohumların kurutulması ve işlenmesi",
      "Tohum depolama, kontrol ve sertifikasyon",
      "Tohum işletmesine teknik gezi",
      "Tohum teknolojisi: kapsam ve temel kavramlar",
      "Organik tarım sistemlerinin mühendislik analizi"
    ],
