    "purpose": "Organik atıkların geri kazanımı süreçlerini, kompostlaştırmanın biyokimyasal temellerini ve toprak verimliliği üzerindeki etkilerini öğretmek.",
    "content": "Atık yönetimi, aerobik/anaerobik süreçler, kompost parametreleri (C/N, pH, nem), endüstriyel yöntemler ve vermikompost uygulamaları.",
    "methods": "1. hafta- Anlatım, soru-yanıt 2. hafta- Anlatım, soru yanıt 3. hafta- Anlatım, soru yanıt, tartışma 4. hafta - Anlatım, soru yanıt, tartışma 5. hafta - Anlatım, soru yanıt, tartışma 6.hafta- Anlatım, soru yanıt, tartışma 7. hafta - Anlatım, soru yanıt, tartışma8. hafta - Anlatım, soru yanıt, tartışma 9. hafta - Anlatım, soru yanıt, tartışma 10. hafta - Anlatım, soru yanıt,tartışma 11. hafta - Anlatım, soru yanıt, tartışma 12. hafta - Anlatım, soru yanıt, tartışma 13. hafta - Anlatım, soru yanıt, tartışma 14. hafta - Anlatım, soru yanıt, tartışma",
    "resources": "Kaynaklar: Akpınar, Ç. (2024). Kompost ders notları. [Yayımlanmamış ders notları].; Ders Notları: Ekinci, K., Tosun, İ., & Varol, N. (2021). Kompost el kitapçığı. T.C. Tarım ve Orman Bakanlığı, Tarımsal Araştırmalar ve Politikalar Genel Müdürlüğü.Aksoy, U., & Altındişli, A. (2002). Ekolojik (organik, biyolojik) tarım. Ekolojik Tarım Organizasyonu Derneği (ETO).",
