    "purpose": "Arı anatomisi ve fizyolojisi, üreme organları ve özellikleri, bal arısı ırkları ırkların belirlenmesinde kullanılan morfolojik ve fizyolojik özellikler incelenecektir",
    "content": "Arıların evrimi, arı anatomisi, sindirim sistemi ve metabolizması, solunum sistemi ve fizyolojisi, dolaşım sistemi ve fizyolojisi, duyu organları ve özellikleri, sinir sistemi ve fonksiyonları , üreme organları ve özellikleri, feremonlar ve etkileri, endokrin organlar ve görevleri, bal arısı ırkları ırkların belirlenmesinde kullanılan morfolojik ve fizyolojik özellikleri.",
    "methods": "Arıların evrimi, arı anatomisinin incelenmesi.Arıların sindirim sistemi ve metabolizmasının incelenmesi.Arıların solunum sistemi ve fizyolojisi, dolaşım sistemi ve fizyolojisi, duyu organları ve özellikleri, sinir sistemi ve fonksiyonlarının incelenmesi.Arıların üreme organları ve özellikleri, feremonlar ve etkileri, endokrin organlar ve görevlerinin incelenmesi. Bal arısı ırkları ırkların belirlenmesinde kullanılan morfolojik ve fizyolojik özelliklerinin incelenmesi.",
    "resources": "Kaynaklar: Matthews, R.W., Matthews, J. R. 1978. Insect Behavior. University of Georgia. A Wiley-Interscience Publication. John Wiley & Sons. New York. 507 pp. Frisch, K. V. 1967. The Dance Language and Orientation of Bees. 526 pp. Dadant, C. C. 1984. The Hive and The Honey Bee. Dadant and Sons. Hamilton. Illinois. 1-740 pp.; Ders Notları: Bal Arısı Yetiştiriciliği - Ürünleri - Hastalıkları- Aydın, 2017Genç, F.; Dodoloğlu, A . 2019. Arıcılığın Temel EsaslarıGenç, F.; Dodoloğlu, A . 2019. Arıcılığın Temel Esaslar",
