    "purpose": "Organik tarım kavramı, ilkeleri ve özelliklerini, organik tarımın tarihçesini, organik tarımdan beklenen yararları, ekonomi, çevre ve sürdürülebilirlik boyutunu ortaya koymak.",
    "content": "Organik Tarım Kavramı, Temel İlkeleri ve Özellikleri, Organik Tarımın Gelişimi, Organik Tarım Kanunu, Organik Ürünlerde Kontrol ve Sertifikasyon, Organik Ürünlerin Üretimi ve Ekonomisi, Yasal Uygulamalar ve Standartlar, Organik Tarımın Ekonomi, Çevre ve Sürdürülebilirlik Boyutu, Organik Ürünlerin Arz ve Talebi, Organik Ürünlerde Tüketici Tercihleri ve Fiyat Oluşum, Organik Ürünlerde Pazarlama Stratejileri ve Pazar Trendleri, Organik Tarım Ürünlerine Yönelik Pazarlama Araştırmaları, Organik Tarımın Geliştirilmesinde Bilgi, Yayım, Eğitim ve Araştırma Olanakları, AB’de ve ABD’de Organik Tarımsal Ürünlere Yönelik Politikalar, Türkiye’de Organik Tarımsal Ürünlere Yönelik Politikalar, Dünyada ve Türkiye’de Organik Tarımın Finansmanı.",
