    "credit": 4,
    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Dr. Öğr. Üyesi Benian Pinar Aktepe benianaktepe@osmaniye.edu.tr",
    "purpose": "Bu dersin amacı, bitki patojenlerinin tanılanmasında kullanılan ileri düzey moleküler, serolojik ve biyokimyasal teknikleri öğretmek ve öğrencilerin farklı tanı yöntemlerini entegre ederek doğru teşhis yapabilmelerini sağlamaktır.",
    "content": "The aim of this course is to teach advanced molecular, serological, and biochemical techniques used in the diagnosis of plant pathogens and to enable students to perform accurate diagnosis by integrating different methods.",
    "methods": "1. hafta - Anlatım + soru-cevap2. hafta - Anlatım + laboratuvar uygulaması3. hafta - Anlatım + uygulama4. hafta - Anlatım + veri analizi5. hafta - Anlatım + uygulama (IF testi)6. hafta - Anlatım + vaka analizi7. hafta - Anlatım + uygulama (API/BIOLOG)8. hafta - Anlatım + uygulama (PCR)9. hafta - Anlatım + literatür inceleme10. hafta - Anlatım + veri yorumlama (FAME)11. hafta - Anlatım + karşılaştırmalı analiz12. hafta - Anlatım + bütünleşik analiz13. hafta - Öğrenci sunumu + tartışma14. hafta - Anlatım + soru-cevap",
    "resources": "Kaynaklar: Ders notları, öğretim üyesi tarafından hazırlanan teorik sunumlar, laboratuvar yönergeleri ve uygulama föylerini içermektedir.; Ders Notları: Schaad, N. W., Jones, J. B., & Chun, W. (2001). Laboratory guide for identification of plant pathogenic bacteria. APS Press.",
    "sdgs": [
      "2",
      "9",
      "12"
    ],
    "outcomes": [
      "Bitki patolojilerinin tanımı için teknikler ıı kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "İleri organik tarım işletmeciliği alanındaki uygulamaları karşılaştırır.",
      "Bitki patolojilerinin tanımı için teknikler ıı için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Bitki patolojilerinin tanımı için teknikler ıı faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Bitki patolojilerinin tanımı için teknikler ıı bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Bitki patojen bakterilerin tanısında temel kavramlar",
      "Protein Analizleri ve Tanıdaki Rolü3 Serolojik yöntemler (ELISA, immünofloresan, aglütinasyon vb.) Serological methods (ELISA, immunofluorescence, agglutination, etc.)",
      "Lipopolisakkarit (LPS) Analizi ve Uygulamaları5 Metabolik profillere göre mikroorganizmaların tanısı (BIOLOG sistemi) Identification based on metabolic profiles (BIOLOG system)",
      "Serolojik Yöntemlere Giriş Introduction to Serological MethodsNucleic acid–based microbial identification methods (PCR, DNA–DNA hybridization)",
      "DELISA ve Diğer Serolojik Testler ELISA and Other Serological Tests",
      "Yağ Asidi Profilleri (FAME/MIDI Sistemine Giriş) Fatty Acid Methyl Ester Profiles (FAME/MIDI System Introduction)",
      "MIDI Sisteminde Tanımlama Süreçleri ve Yorumlama Identification and Interpretation Using the MIDI System",
      "PCR, RT-PCR ve Sekans Analizi ile Tanı Diagnosis via PCR, RT-PCR, and Sequencing Analysis",
      "Metabolik Profiller (BIOLOG Sistemi) Temelleri Basics of Metabolic Profiles (BIOLOG System)",
      "BIOLOG ile Mikrobiyal Tanılama ve Veri Analizi Microbial Identification and Data Analysis Using BIOLOG",
      "Nükleik Asit Temelli Tanı Yöntemlerine Giriş Introduction to Nucleic Acid-Based Diagnostic Methods",
      "Moleküler Filogeni ve Veri Yorumlama Molecular Phylogeny and Data Interpretation",
      "Laboratuvar Sterilizasyonu ve Dezenfeksiyon Teknikleri.",
      "İş Sağlığı ve Güvenliği (İSG) ve Genel Değerlendirme Laboratory Sterilization and Disinfection Techniques. Occupational Health and Safety (OHS) and General Evaluation",
      "Bitki patolojilerinin tanımı için teknikler ıı: kapsam ve temel kavramlar"
    ],
