    "content": "Tohum patolojisi; organik tarım sistemlerinin mühendislik analizi, kütle ve enerji dengeleri, proses değişkenleri, deneysel ölçüm ve modelleme, proses tasarımı ve optimizasyon, ürün güvenliği ve kalite, sürdürülebilir üretim, güncel organik tarım teknolojileri boyutlarıyla ele alınır.",
